class Solution:
    def equalSubstring(self, s, t, maxCost):
        left = 0
        for right in range(len(s)):
            maxCost -= abs(ord(s[right])-ord(t[right]))
            if maxCost < 0:
                maxCost += abs(ord(s[left])-ord(t[left]))
                left += 1
        return (right+1)-left

class Solution:
    def removeDuplicates(self, s: str, k: int) -> str:
        stack=[]
        res=''
        for i in range(len(s)):
            if len(stack)==0:
                stack.append([s[i],1])
            elif stack[-1][0]==s[i]:
                stack[-1][1]=stack[-1][1]+1
            else:
                stack.append([s[i],1])
            if stack[-1][1]==k:
                stack.pop()
        for i in range(len(stack)):
            res+=stack[i][0]*stack[i][1]
        return res

class Solution:
    def removeDuplicates(self, s: str, k: int) -> str:
        stk = [['^', 0]]
        for c in s:
            if stk[-1][0] == c:
                stk[-1][1] += 1
                if stk[-1][1] == k:
                    stk.pop()
            else:
                stk.append([c, 1])
        return "".join(c*k for c, k in stk)

