    def minimumMoves(self, grid: List[List[int]]) -> int:
        queue , vis , n = [(0,1,0,0)] , {} , len(grid)
        while queue:
            x,y,pos,moves = queue.pop(0)
            if x == y == n-1 and pos == 0: return moves
            if pos == 0:
                if y + 1 < n and grid[x][y+1] == 0 and (x,y+1,0) not in vis:
