                    if (x+1,y-1,1) not in vis:
                        vis[(x+1,y-1,1)] = True
                        queue.append((x+1,y-1,1,moves+1))
                    if (x+1,y,0) not in vis:
                        vis[(x+1,y,0)] = True
                        queue.append((x+1,y,0,moves+1))
            else:
